'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const E=require('./engine.js');
(async()=>{const file=process.argv[2];if(!file)throw Error('Usage: node verify-handoff.cjs handoff.json');const st=fs.statSync(file);if(st.size>4194304)throw Error('Handoff exceeds 4 MiB.');const digest=crypto.createHash('sha256').update('axm-industrial-engine/1\0').update(fs.readFileSync(path.join(__dirname,'engine.js'))).update('\0').update(fs.readFileSync(path.join(__dirname,'commons-core.js'))).digest('hex');const s=await E.restore(JSON.parse(fs.readFileSync(file,'utf8')),digest);console.log(JSON.stringify({status:'PASS',engine_sha256:digest,sources:s.sources.length,decisions:s.decisions.length,reviews:s.reviews.length,latest_current:E.current(s),review_status:E.reviewStatus(s),operational_authority:false,physical_truth:'unverified',model_calls:0,conclusions:s.decisions.map(d=>({sequence:d.sequence,status:d.result.status,chosen:d.result.chosen,net_cents:d.result.plan?.net_cents}))},null,2));})().catch(e=>{console.error(JSON.stringify({status:'FAIL',error:e.message}));process.exitCode=1});
